function ChartTile({
  title,
  description,
  children,
  context,
}: {
  title: string;
  description?: string;
  children: React.ReactNode;
  /** Annotation context label shown in the add-annotation modal */
  context?: string;
}) {
  const { timeframe: appTf } = useAppTimeframe();
  const fromMs = new Date(appTf.from).getTime();
  const toMs = new Date(appTf.to).getTime();
  const [maximized, setMaximized] = useState(false);
  return (
    <>
      {maximized && (
        <div className="svc-chart-overlay" onClick={() => setMaximized(false)}>
          <div className="svc-chart-maximized" onClick={(e) => e.stopPropagation()}>
            <div className="chart-title-row">
              <div className="chart-title">{title}</div>
              <button className="svc-chart-toggle" onClick={() => setMaximized(false)} title="Minimize">
                <MinimizeIcon />
              </button>
            </div>
            {description && <div className="chart-description">{description}</div>}
            <AnnotationStrip fromMs={fromMs} toMs={toMs} context={context ?? title} />
            <div className="chart-body">{children}</div>
          </div>
        </div>
      )}
      <div className="svc-chart-tile">
        <div className="chart-title-row">
          <div className="chart-title">{title}</div>
          <button className="svc-chart-toggle" onClick={() => setMaximized(true)} title="Maximize">
            <MaximizeIcon />
          </button>
        </div>
        {description && <div className="chart-description">{description}</div>}
        <AnnotationStrip fromMs={fromMs} toMs={toMs} context={context ?? title} />
        <div className="chart-body">{children}</div>
      </div>
    </>
  );
}

