const LINK_STYLE: React.CSSProperties = {
  color: "#6babf5",
  textDecoration: "none",
  cursor: "pointer",
};

/** Build timeframe query params (use '?' for first param, '&' to append) */
function tfParams(from: string, to: string): string {
  const enc = (v: string) => encodeURIComponent(v).replace(/\(/g, '%28').replace(/\)/g, '%29');
  return `from=${enc(from)}&to=${enc(to)}`;
}

/** Build tf= param for Dynatrace app links (e.g. tf=now-7d;now) */
function tfAppParam(from: string, to: string): string {
  const clean = (s: string) => s.replace(/now\(\)/g, 'now');
  return `tf=${encodeURIComponent(clean(from) + ';' + clean(to))}`;
}

/** Reusable cell renderer that links a service name to Distributed Traces */
const makeServiceLinkCell = (envUrl: string, from: string, to: string) =>
  ({ value, rowData }: { value: string; rowData: any }) => {
    const svcId = rowData["dt.entity.service"];
    if (!svcId) return <span>{value}</span>;
    const url = `${envUrl}/ui/apps/dynatrace.distributedtracing/explorer?filter=dt.entity.service+%3D+${encodeURIComponent(svcId)}&${tfParams(from, to)}`;
    return (
      <a href={url} target="_blank" rel="noopener noreferrer" style={LINK_STYLE}>
        {value}
      </a>
    );
  };

const makeSmartscapeLinkCell = (envUrl: string, from: string, to: string) =>
  ({ value, rowData }: { value: string; rowData: any }) => {
    const svcId = rowData["dt.entity.service"];
    if (!svcId) return <span>{value}</span>;
    const url = `${envUrl}/ui/apps/dynatrace.smartscape/view/dynatrace.smartscape.vertical-topology/${svcId}?${tfParams(from, to)}`;
    return (
      <a href={url} target="_blank" rel="noopener noreferrer" style={LINK_STYLE}>
        {value}
      </a>
    );
  };

const makeServicesLinkCell = (envUrl: string, from: string, to: string) =>
  ({ value, rowData }: { value: string; rowData: any }) => {
    const svcId = rowData["dt.entity.service"];
    if (!svcId) return <span>{value}</span>;
    const tf = encodeURIComponent(from.replace(/\(\)/g, '') + ';' + to.replace(/\(\)/g, ''));
    const url = `${envUrl}/ui/apps/dynatrace.services/explorer/services?perspective=performance&sort=entity%3Aascending&detailsId=${svcId}&sidebarOpen=false&tf=${tf}`;
    return (
      <a href={url} target="_blank" rel="noopener noreferrer" style={LINK_STYLE}>
        {value}
      </a>
    );
  };

function fmtMinutes(minutes: number): string {
  if (!minutes || minutes <= 0) return "0m";
  if (minutes < 1) return `${Math.round(minutes * 60)}s`;
  if (minutes < 60) return `${Math.round(minutes * 10) / 10}m`;
  const h = Math.floor(minutes / 60);
  const m = Math.round(minutes % 60);
  if (h < 24) return m > 0 ? `${h}h ${m}m` : `${h}h`;
  const d = Math.floor(h / 24);
  const rh = h % 24;
  return rh > 0 ? `${d}d ${rh}h` : `${d}d`;
}

