  if (highRestarts.length > 0) { insights.push({ severity: "warning", icon: "⚠️", text: `${highRestarts.length} namespace(s) with high restart counts (>5) — OOMKill or liveness probe failures indicating sizing issues: ${highRestarts.slice(0,3).map(d => d.Namespace ?? "").join(", ")}${highRestarts.length > 3 ? "..." : ""}` }); recs.push({ impact: "high", text: "High restart counts in a namespace indicate systematic OOMKill or CrashLoopBackOff. Audit memory limits and liveness probe thresholds for all workloads in these namespaces." }); }
