  // Map DATABASE_SERVICE entity ID → underlying custom device entity ID (for database overview drilldown)
  const dbEntityMap = useMemo(() => {
    const m = new Map<string, string>();
    svcEntityTypesResult.data?.records?.forEach((r: any) => {
      if (String(r.serviceType ?? "") !== "DATABASE_SERVICE") return;
      const id = String(r.id ?? "");
      const raw = r.dbDevice;
      const devId = Array.isArray(raw) ? String(raw[0] ?? "") : String(raw ?? "");
      if (id && devId && devId !== "null" && devId !== "undefined") m.set(id, devId);
    });
    return m;
  }, [svcEntityTypesResult.data]);

  // ─── Endpoint Heatmap ───
  const endpointHeatmapData: HoneycombTileNumericData[] = useMemo(() => {
    if (!reqDetailsData.length) return [];
    return reqDetailsData.map((r) => ({
      name: `${r.Service} — ${r.Request}`,
      value: (r.FailureRate as number) ?? 0,
    }));
  }, [reqDetailsData]);
  const endpointHeatmapColors = [
    { from: 0, to: 0.5, color: GREEN },
    { from: 0.5, to: 2, color: YELLOW },
    { from: 2, to: 100, color: RED },
  ];
  const svcEntityMap = useMemo(() => {
    const m = new Map<string, string>();
    reqDetailsData.forEach(r => { if (r["dt.entity.service"] && r.Service) m.set(r.Service, r["dt.entity.service"] as string); });
    return m;
  }, [reqDetailsData]);

  // ─── MTTR / MTTA ───
  const mttrData = useMemo(() => {
    if (!closedProblemsResult.data?.records) return { problems: [] as any[], mttr: 0, count: 0 };
    const problems = closedProblemsResult.data.records.map((r) => ({
      ID: (r["display_id"] as string) ?? "",
      "event.id": (r["event.id"] as string) ?? "",
      Problem: (r["event.name"] as string) ?? "",
      Start: r["event.start"] ? new Date(r["event.start"] as string).toLocaleString() : "",
      End: r["event.end"] ? new Date(r["event.end"] as string).toLocaleString() : "",
      "Duration (min)": Math.round(((r["duration_minutes"] as number) ?? 0) * 10) / 10,
      "Root Cause": (r["root_cause_entity_name"] as string) ?? "",
    }));
    const durations = closedProblemsResult.data.records
      .map((r) => (r["duration_minutes"] as number) ?? 0)
      .filter((d) => d > 0);
    const mttr = durations.length > 0 ? durations.reduce((a, b) => a + b, 0) / durations.length : 0;
    return { problems, mttr, count: durations.length };
  }, [closedProblemsResult.data]);

  const mttrPrevData = useMemo(() => {
    if (!closedProblemsPrevResult.data?.records) return { mttr: 0, count: 0 };
    const durations = closedProblemsPrevResult.data.records
      .map((r) => (r["duration_minutes"] as number) ?? 0)
      .filter((d) => d > 0);
    const mttr = durations.length > 0 ? durations.reduce((a, b) => a + b, 0) / durations.length : 0;
    return { mttr, count: durations.length };
  }, [closedProblemsPrevResult.data]);

  // ─── Anomaly Detection ───
  const anomalyData = useMemo(() => {
    const current = anomalyCurrentResult.data?.records;
    const baseline = anomalyBaselineResult.data?.records;
    if (!current || !baseline) return [];
    const baselineMap = new Map<string, Record<string, unknown>>();
    baseline.forEach((r) => { baselineMap.set(r["dt.entity.service"] as string, r); });
    return current.map((r) => {
      const svcId = r["dt.entity.service"] as string;
      const base = baselineMap.get(svcId);
      const curLatency = (r["avgLatencyP90"] as number) ?? 0;
      const curErrorRate = (r["errorRate"] as number) ?? 0;
      const curRequests = (r["avgRequests"] as number) ?? 0;
      const baseLatency = base ? ((base["avgLatencyP90"] as number) ?? 0) : 0;
      const baseErrorRate = base ? ((base["errorRate"] as number) ?? 0) : 0;
      const baseRequests = base ? ((base["avgRequests"] as number) ?? 0) : 0;
      const latencyChange = baseLatency > 0 ? ((curLatency - baseLatency) / baseLatency) * 100 : 0;
      const errorRateChange = baseErrorRate > 0 ? ((curErrorRate - baseErrorRate) / baseErrorRate) * 100 : curErrorRate > 0 ? 100 : 0;
      const requestsChange = baseRequests > 0 ? ((curRequests - baseRequests) / baseRequests) * 100 : 0;
      const isAnomaly = Math.abs(latencyChange) > 50 || Math.abs(errorRateChange) > 100 || curErrorRate > 5;
      return {
        Service: (r["Service"] as string) ?? "",
        "dt.entity.service": svcId,
        "Latency P90 (now)": Math.round(curLatency),
        "Latency P90 (baseline)": Math.round(baseLatency),
        "Latency Change %": Math.round(latencyChange * 10) / 10,
        "Error Rate (now)": Math.round(curErrorRate * 1000) / 1000,
        "Error Rate (baseline)": Math.round(baseErrorRate * 1000) / 1000,
        "Error Rate Change %": Math.round(errorRateChange * 10) / 10,
        "Requests Δ %": Math.round(requestsChange * 10) / 10,
        Anomaly: isAnomaly ? "YES" : "—",
      };
    }).sort((a, b) => (b.Anomaly === "YES" ? 1 : 0) - (a.Anomaly === "YES" ? 1 : 0) || Math.abs(b["Latency Change %"]) - Math.abs(a["Latency Change %"]));
  }, [anomalyCurrentResult.data, anomalyBaselineResult.data]);

  // ─── Endpoint Heatmap — hourly grid with 2σ anomaly flags ───
  const heatmapGridData = useMemo(() => {
    const records = endpointHourlyResult.data?.records;
    const prevRecords = endpointPrevWeekResult.data?.records;
    if (!records?.length) return { cells: [] as any[], worstSlot: null as any };
    // Build baseline stats per service per hour-of-day from prev week
    const baselineByHour = new Map<string, { values: number[] }>();
    prevRecords?.forEach((r: any) => {
      const svc = (r["Service"] as string) ?? "";
      const tf = r["timeframe"] as any;
      if (!tf?.start) return;
      const hour = new Date(tf.start).getHours();
      const key = `${svc}__${hour}`;
      const val = heatmapMetric === "errorRate"
        ? ((r["errors"]?.[0] ?? 0) > 0 && (r["requests"]?.[0] ?? 0) > 0 ? ((r["errors"][0] as number) / (r["requests"][0] as number)) * 100 : 0)
        : heatmapMetric === "P50" ? (r["latencyP50"]?.[0] ?? 0)
        : heatmapMetric === "P90" ? (r["latencyP90"]?.[0] ?? 0)
        : (r["latencyP99"]?.[0] ?? 0);
      if (!baselineByHour.has(key)) baselineByHour.set(key, { values: [] });
      baselineByHour.get(key)!.values.push(Number(val));
    });
    // Compute mean/std per key
    const stats = new Map<string, { mean: number; std: number }>();
    baselineByHour.forEach((v, k) => {
      const mean = v.values.reduce((a, b) => a + b, 0) / v.values.length;
      const variance = v.values.reduce((a, b) => a + (b - mean) ** 2, 0) / v.values.length;
      stats.set(k, { mean, std: Math.sqrt(variance) });
    });
    // Build cells from current data
    let worstSlot: { service: string; day: string; hour: number; value: number; deviation: number } | null = null;
    const cells = records.map((r: any) => {
      const svc = (r["Service"] as string) ?? "";
      const tf = r["timeframe"] as any;
      if (!tf?.start) return null;
      const dt = new Date(tf.start);
      const hour = dt.getHours();
      const day = dt.toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" });
      const val = heatmapMetric === "errorRate"
        ? ((r["errors"]?.[0] ?? 0) > 0 && (r["requests"]?.[0] ?? 0) > 0 ? ((r["errors"][0] as number) / (r["requests"][0] as number)) * 100 : 0)
        : heatmapMetric === "P50" ? (r["latencyP50"]?.[0] ?? 0)
        : heatmapMetric === "P90" ? (r["latencyP90"]?.[0] ?? 0)
        : (r["latencyP99"]?.[0] ?? 0);
      const numVal = Number(val);
      const key = `${svc}__${hour}`;
      const baseline = stats.get(key);
      const deviation = baseline && baseline.std > 0 ? (numVal - baseline.mean) / baseline.std : 0;
      const isAnomaly = Math.abs(deviation) > 2;
      if (isAnomaly && (!worstSlot || Math.abs(deviation) > Math.abs(worstSlot.deviation))) {
        worstSlot = { service: svc, day, hour, value: numVal, deviation };
      }
      return { service: svc, day, hour, value: numVal, deviation, isAnomaly };
    }).filter(Boolean);
    return { cells, worstSlot };
  }, [endpointHourlyResult.data, endpointPrevWeekResult.data, heatmapMetric]);

  // ─── MTTR — team benchmark (percentile relative to all services) ───
  const mttrBenchmark = useMemo(() => {
    const allRecords = mttrAllSvcsResult.data?.records;
    if (!allRecords?.length || !mttrData.mttr) return { percentile: 0, allMttr: 0, count: 0 };
    const durations = allRecords.map((r: any) => Number(r["duration_minutes"] ?? 0)).filter((d: number) => d > 0).sort((a: number, b: number) => a - b);
    if (!durations.length) return { percentile: 0, allMttr: 0, count: 0 };
    const rank = durations.filter((d: number) => d <= mttrData.mttr).length;
    const percentile = Math.round((rank / durations.length) * 100);
    const allMttr = durations.reduce((a: number, b: number) => a + b, 0) / durations.length;
    return { percentile, allMttr: Math.round(allMttr * 10) / 10, count: durations.length };
  }, [mttrAllSvcsResult.data, mttrData.mttr]);

  // ─── MTTR — trend forecast ───
  const mttrForecast = useMemo(() => {
    const allRecords = mttrAllSvcsResult.data?.records;
    if (!allRecords?.length) return null;
    // Split last 30 days into two halves
    const sorted = [...allRecords].sort((a: any, b: any) => new Date(a["event.start"] as string).getTime() - new Date(b["event.start"] as string).getTime());
    const mid = Math.floor(sorted.length / 2);
    const firstHalf = sorted.slice(0, mid).map((r: any) => Number(r["duration_minutes"] ?? 0)).filter((d: number) => d > 0);
    const secondHalf = sorted.slice(mid).map((r: any) => Number(r["duration_minutes"] ?? 0)).filter((d: number) => d > 0);
    if (!firstHalf.length || !secondHalf.length) return null;
    const avgFirst = firstHalf.reduce((a, b) => a + b, 0) / firstHalf.length;
    const avgSecond = secondHalf.reduce((a, b) => a + b, 0) / secondHalf.length;
    const trendPerDay = (avgSecond - avgFirst) / 15; // 15 days per half
    const target = 30; // 30-min MTTR target
    if (trendPerDay >= 0 && avgSecond > target) return { improving: false, trendPerDay: Math.round(trendPerDay * 100) / 100, current: Math.round(avgSecond), target, daysToTarget: null as number | null };
    if (avgSecond <= target) return { improving: true, trendPerDay: Math.round(trendPerDay * 100) / 100, current: Math.round(avgSecond), target, daysToTarget: 0 };
    const daysToTarget = Math.ceil((avgSecond - target) / Math.abs(trendPerDay));
    return { improving: true, trendPerDay: Math.round(trendPerDay * 100) / 100, current: Math.round(avgSecond), target, daysToTarget };
  }, [mttrAllSvcsResult.data]);

  // ─── MTTR — repeat offenders ───
  const repeatOffenders = useMemo(() => {
    const records = mttrRepeatResult.data?.records;
    if (!records?.length) return [];
    return records.slice(0, 5).map((r: any) => ({
      entity: (r["root_cause_entity_name"] as string) ?? "",
      occurrences: Number(r["occurrences"] ?? 0),
      avgDuration: Math.round(Number(r["avgDuration"] ?? 0) * 10) / 10,
      lastSeen: r["lastSeen"] ? new Date(r["lastSeen"] as string).toLocaleDateString() : "",
    }));
  }, [mttrRepeatResult.data]);

  // ─── Anomaly Detection — correlation panel ───
  const anomalyCorrelations = useMemo(() => {
    if (!anomalyData.length) return [];
    const activeAnomalies = anomalyData.filter(a => a.Anomaly === "YES");
    if (!activeAnomalies.length) return [];
    // Group non-anomalous services that show moderate deviation in the same direction
    const correlations: Array<{ anomalyService: string; anomalyServiceId: string; correlatedServices: Array<{ name: string; strength: number; entityId: string }> }> = [];
    activeAnomalies.forEach(anom => {
      const correlated = anomalyData
        .filter(s => s.Service !== anom.Service && s.Anomaly !== "YES")
        .filter(s => {
          const latDir = Math.sign(anom["Latency Change %"]) === Math.sign(s["Latency Change %"]);
          const errDir = Math.sign(anom["Error Rate Change %"]) === Math.sign(s["Error Rate Change %"]);
          return (latDir && Math.abs(s["Latency Change %"]) > 10) || (errDir && Math.abs(s["Error Rate Change %"]) > 20);
        })
        .map(s => ({
          name: s.Service,
          entityId: s["dt.entity.service"] as string,
          strength: Math.round(Math.min(100, (Math.abs(s["Latency Change %"]) + Math.abs(s["Error Rate Change %"])) / 2)),
        }))
        .sort((a, b) => b.strength - a.strength)
        .slice(0, 5);
      if (correlated.length) correlations.push({ anomalyService: anom.Service, anomalyServiceId: anom["dt.entity.service"] as string, correlatedServices: correlated });
    });
    return correlations;
  }, [anomalyData]);

  // ─── Anomaly Detection — filtered (suppressed) view ───
  const filteredAnomalyData = useMemo(() => {
    const suppressedSet = new Set(anomalySuppressions.map(s => s.service));
    return anomalyData.map(a => ({ ...a, suppressed: suppressedSet.has(a.Service) }));
  }, [anomalyData, anomalySuppressions]);

  // ─── Deployment Events ───
  const deploymentsData = useMemo(() => {
    if (!deploymentsResult.data?.records) return [];
    return deploymentsResult.data.records.map((r) => ({
      Time: r["timestamp"] ? new Date(r["timestamp"] as string).toLocaleString() : "",
      timestamp: r["timestamp"] ? new Date(r["timestamp"] as string).getTime() : 0,
      Event: (r["event.name"] as string) ?? "",
      Service: (r["serviceName"] as string) ?? "",
      "dt.entity.service": (r["dt.entity.service"] as string) ?? "",
    }));
  }, [deploymentsResult.data]);

  // ─── Overview: Executive Summary KPIs ───
  const overviewKpis = useMemo(() => {
    const totalRequests = svcDetailsData.reduce((s, r) => s + (r.Requests ?? 0), 0);
    const totalFailures = svcDetailsData.reduce((s, r) => s + (r.Failures ?? 0), 0);
    const avgLatency = svcDetailsData.length ? svcDetailsData.reduce((s, r) => s + (r.Latency_Avg ?? 0), 0) / svcDetailsData.length : 0;
    const avgP90 = svcDetailsData.length ? svcDetailsData.reduce((s, r) => s + (r.Latency_p90 ?? 0), 0) / svcDetailsData.length : 0;
    const errorRate = totalRequests > 0 ? (totalFailures / totalRequests) * 100 : 0;
    const activeProblems = problemsData.filter(p => p.Status === "ACTIVE").length;
    const affectedServices = honeycombData.filter(h => h.value === 1).length;
    const budgetPercent = 100 - sloTarget;
    const sloBreaches = svcDetailsData.filter(s => {
      const er = (s.FailureRate ?? 0);
      return budgetPercent > 0 && (er / budgetPercent) * 100 >= 100;
    }).length;
    return { totalRequests, totalFailures, avgLatency, avgP90, errorRate, activeProblems, affectedServices, sloBreaches };
  }, [svcDetailsData, problemsData, honeycombData, sloTarget]);

  // ─── Overview: Top 3 Risks (Davis anomalies + SLO burn rates combined) ───
  const top3Risks = useMemo(() => {
    const risks: { severity: "critical" | "warning"; text: string }[] = [];
    // SLO budget exhausted services
    const budgetPercent = 100 - sloTarget;
    const exhaustedSvcs = svcDetailsData.filter(s => budgetPercent > 0 && ((s.FailureRate ?? 0) / budgetPercent) * 100 >= 100);
    if (exhaustedSvcs.length > 0) risks.push({ severity: "critical", text: `${exhaustedSvcs.length} service${exhaustedSvcs.length > 1 ? "s" : ""} exhausted SLO error budget: ${exhaustedSvcs.slice(0, 2).map(s => s.Service).join(", ")}${exhaustedSvcs.length > 2 ? " +" + (exhaustedSvcs.length - 2) + " more" : ""}` });
    // Active problems
    const activeProblems = problemsData.filter(p => p.Status === "ACTIVE");
    if (activeProblems.length > 0) risks.push({ severity: "critical", text: `${activeProblems.length} active Davis problem${activeProblems.length > 1 ? "s" : ""}: ${activeProblems.slice(0, 2).map(p => p.Description).join("; ")}${activeProblems.length > 2 ? "..." : ""}` });
    // Anomalous services
    const anomalous = anomalyData.filter(a => a.Anomaly === "YES");
    if (anomalous.length > 0) risks.push({ severity: "warning", text: `${anomalous.length} service${anomalous.length > 1 ? "s" : ""} showing anomalous behavior vs baseline: ${anomalous.slice(0, 2).map(a => a.Service).join(", ")}${anomalous.length > 2 ? "..." : ""}` });
    // High burn rate services
    const highBurn = svcDetailsData.filter(s => budgetPercent > 0 && ((s.FailureRate ?? 0) / budgetPercent) >= 2 && ((s.FailureRate ?? 0) / budgetPercent) * 100 < 100);
    if (highBurn.length > 0) risks.push({ severity: "warning", text: `${highBurn.length} service${highBurn.length > 1 ? "s" : ""} burning SLO budget at 2x+ rate: ${highBurn.slice(0, 2).map(s => s.Service).join(", ")}${highBurn.length > 2 ? "..." : ""}` });
    return risks.slice(0, 3);
  }, [svcDetailsData, problemsData, anomalyData, sloTarget]);

  const inferredDeployRegressionsByService = useMemo(() => {
    const map = new Map<string, number>();
    const records = (changeImpactResult.data?.records ?? []) as any[];
    records.forEach((r) => {
      const svc = String(r["service.name"] ?? r["entity.name"] ?? r["dt.entity.service"] ?? "");
      if (!svc) return;
      const req = (r["requests"] as number[] | undefined) ?? [];
      const fail = (r["failures"] as number[] | undefined) ?? [];
      const lat = (r["latency_p90"] as number[] | undefined) ?? [];
      if (req.length < 4 || fail.length < 4 || lat.length < 4) return;
      const mid = Math.floor(req.length / 2);
      const reqBefore = req.slice(0, mid).reduce((a, b) => a + (b ?? 0), 0);
      const reqAfter = req.slice(mid).reduce((a, b) => a + (b ?? 0), 0);
      const failBefore = fail.slice(0, mid).reduce((a, b) => a + (b ?? 0), 0);
      const failAfter = fail.slice(mid).reduce((a, b) => a + (b ?? 0), 0);
      const latBefore = lat.slice(0, mid).reduce((a, b) => a + (b ?? 0), 0) / Math.max(1, mid);
      const latAfter = lat.slice(mid).reduce((a, b) => a + (b ?? 0), 0) / Math.max(1, lat.length - mid);
      const errBefore = reqBefore > 0 ? (failBefore / reqBefore) * 100 : 0;
      const errAfter = reqAfter > 0 ? (failAfter / reqAfter) * 100 : 0;
      if (latAfter > latBefore * 1.2 || errAfter > errBefore + 0.5) {
        map.set(svc, (map.get(svc) ?? 0) + 1);
      }
    });
    return map;
  }, [changeImpactResult.data]);

  const inferredDeployRegressionCount = useMemo(() => {
    let total = 0;
    inferredDeployRegressionsByService.forEach((v) => { total += v; });
    return total;
  }, [inferredDeployRegressionsByService]);

  const inferredDeployRegressionPrevCount = useMemo(() => {
    const records = (changeImpactPrevResult.data?.records ?? []) as any[];
    if (!records.length) return 0;
    let total = 0;
    records.forEach((r) => {
      const req = (r["requests"] as number[] | undefined) ?? [];
      const fail = (r["failures"] as number[] | undefined) ?? [];
      const lat = (r["latency_p90"] as number[] | undefined) ?? [];
      if (req.length < 4 || fail.length < 4 || lat.length < 4) return;
      const mid = Math.floor(req.length / 2);
      const reqBefore = req.slice(0, mid).reduce((a, b) => a + (b ?? 0), 0);
      const reqAfter = req.slice(mid).reduce((a, b) => a + (b ?? 0), 0);
      const failBefore = fail.slice(0, mid).reduce((a, b) => a + (b ?? 0), 0);
      const failAfter = fail.slice(mid).reduce((a, b) => a + (b ?? 0), 0);
      const latBefore = lat.slice(0, mid).reduce((a, b) => a + (b ?? 0), 0) / Math.max(1, mid);
      const latAfter = lat.slice(mid).reduce((a, b) => a + (b ?? 0), 0) / Math.max(1, lat.length - mid);
      const errBefore = reqBefore > 0 ? (failBefore / reqBefore) * 100 : 0;
      const errAfter = reqAfter > 0 ? (failAfter / reqAfter) * 100 : 0;
      if (latAfter > latBefore * 1.2 || errAfter > errBefore + 0.5) total += 1;
    });
    return total;
  }, [changeImpactPrevResult.data]);

  const earlyWarningSignals = useMemo(() => {
    const signals: Array<{ severity: "warning" | "critical"; text: string }> = [];
    if (overviewKpisPrev) {
      const p90Growth = overviewKpisPrev.avgP90 > 0 ? ((overviewKpis.avgP90 - overviewKpisPrev.avgP90) / overviewKpisPrev.avgP90) * 100 : 0;
      const errGrowth = overviewKpisPrev.errorRate > 0 ? ((overviewKpis.errorRate - overviewKpisPrev.errorRate) / overviewKpisPrev.errorRate) * 100 : 0;
      const problemsDelta = (overviewKpis.activeProblems ?? 0) - (overviewKpisPrev.activeProblems ?? 0);
      if (p90Growth > 20) signals.push({ severity: p90Growth > 40 ? "critical" : "warning", text: `P90 drift +${p90Growth.toFixed(0)}% vs previous period.` });
      if (errGrowth > 30 || overviewKpis.errorRate > 1.5) signals.push({ severity: errGrowth > 60 ? "critical" : "warning", text: `Error-rate drift ${errGrowth > 0 ? "+" : ""}${errGrowth.toFixed(0)}% with current ${overviewKpis.errorRate.toFixed(2)}%.` });
      if (problemsDelta > 0) signals.push({ severity: problemsDelta >= 3 ? "critical" : "warning", text: `Active Davis problems increased by ${problemsDelta}.` });
    }
    if (inferredDeployRegressionCount > 0) {
      signals.push({ severity: "warning", text: "Recent deployment regressions detected; elevated near-term incident probability." });
    }
    return signals.slice(0, 4);
  }, [overviewKpis, overviewKpisPrev, inferredDeployRegressionCount]);

  const businessImpact = useMemo(() => {
    const atRiskFraction = Math.min(0.95, (overviewKpis.errorRate / 100) + (overviewKpis.activeProblems * 0.05));
    const atRiskRequests = Math.round(overviewKpis.totalRequests * atRiskFraction);
    const estimatedRevenueAtRisk = atRiskRequests * businessValuePerRequest;
    const affectedUsersEstimate = Math.round(atRiskRequests * 0.65);
    return {
      atRiskFraction,
      atRiskRequests,
      estimatedRevenueAtRisk,
      affectedUsersEstimate,
    };
  }, [overviewKpis, businessValuePerRequest]);

  const businessImpactPrev = useMemo(() => {
    if (!overviewKpisPrev) return null;
    const atRiskFraction = Math.min(0.95, (overviewKpisPrev.errorRate / 100) + ((overviewKpisPrev.activeProblems ?? 0) * 0.05));
    const atRiskRequests = Math.round((overviewKpisPrev.totalRequests ?? 0) * atRiskFraction);
    const estimatedRevenueAtRisk = atRiskRequests * businessValuePerRequest;
    return {
      atRiskFraction,
      atRiskRequests,
      estimatedRevenueAtRisk,
    };
  }, [overviewKpisPrev, businessValuePerRequest]);

  const incidentCommander = useMemo(() => {
    const modeProfile = incidentCommandMode === "stabilize"
      ? { impactFactor: 1, revenueFactor: 1, confidenceBoost: 10, actions: [
        "Stabilize top error-budget burner by reducing traffic or disabling risky features.",
        "Isolate the most probable dependency edge and apply circuit-breaker or timeout tightening.",
        "Validate latest deployment for rollback criteria and execute if regression threshold exceeded.",
      ] }
      : incidentCommandMode === "mitigate"
        ? { impactFactor: 0.65, revenueFactor: 0.7, confidenceBoost: 2, actions: [
          "Mitigate user impact with progressive traffic steering to healthier zones.",
          "Apply temporary safeguards: stricter rate limits, shorter timeouts, and fallback responses.",
          "Contain blast radius by pausing non-critical deploys and noisy background jobs.",
        ] }
        : { impactFactor: 0.35, revenueFactor: 0.4, confidenceBoost: -6, actions: [
          "Start phased recovery of highest-value service paths first, then expand gradually.",
          "Remove temporary mitigations in reverse order while watching error and latency guardrails.",
          "Run post-incident validation and confirm SLO burn returns to baseline before full reopen.",
        ] };

    const strongestCorrelated = anomalyCorrelations[0]?.correlatedServices?.[0]
      ? {
          service1: anomalyCorrelations[0].anomalyService,
          service1Id: anomalyCorrelations[0].anomalyServiceId,
          service2: anomalyCorrelations[0].correlatedServices[0].name,
          service2Id: anomalyCorrelations[0].correlatedServices[0].entityId,
          correlation: (anomalyCorrelations[0].correlatedServices[0].strength ?? 0) / 100,
        }
      : undefined;
    const likelyRootCause = problemsData.find((p) => p.Status === "ACTIVE")?.RootCause || strongestCorrelated?.service1 || "Undetermined";
    const impactedServicesBase = Math.max(overviewKpis.affectedServices, problemsData.reduce((acc, p) => acc + ((p.Affected as string[] | undefined)?.length ?? 0), 0));
    const impactedServices = Math.max(1, Math.round(impactedServicesBase * modeProfile.impactFactor));
    const rootCauseConfidence = Math.min(99, Math.max(35, (problemsData.some((p) => p.Status === "ACTIVE") ? 88 : 62) + Math.round((strongestCorrelated?.correlation ?? 0) * 12) + modeProfile.confidenceBoost));
    const correlatedStrength = Math.round((strongestCorrelated?.correlation ?? 0) * 100);
    const revenueAtRisk = businessImpact.estimatedRevenueAtRisk * modeProfile.revenueFactor;
    const rootCauseId = svcDetailsData.find((s) => s.Service === likelyRootCause)?.["dt.entity.service"] as string | undefined;
    const rootCauseUrl = rootCauseId
      ? `${envUrl}/ui/apps/dynatrace.distributedtracing/explorer?filter=dt.entity.service+%3D+${encodeURIComponent(rootCauseId)}&${tfParams(tfFrom, tfTo)}`
      : `${envUrl}/ui/apps/dynatrace.davis.problems/?${tfParams(tfFrom, tfTo)}`;
    const correlatedUrl = strongestCorrelated?.service2Id
      ? `${envUrl}/ui/apps/dynatrace.distributedtracing/explorer?filter=dt.entity.service+%3D+${encodeURIComponent(strongestCorrelated.service2Id)}&${tfParams(tfFrom, tfTo)}`
      : `${envUrl}/ui/apps/dynatrace.distributedtracing/explorer?${tfParams(tfFrom, tfTo)}`;
    return {
      likelyRootCause,
      rootCauseUrl,
      rootCauseConfidence,
      impactedServices,
      strongestCorrelated,
      correlatedStrength,
      revenueAtRisk,
      correlatedUrl,
      nextActions: modeProfile.actions,
      mode: incidentCommandMode,
    };
  }, [problemsData, anomalyCorrelations, overviewKpis, incidentCommandMode, svcDetailsData, envUrl, tfFrom, tfTo, businessImpact.estimatedRevenueAtRisk]);

  const incidentCommanderPrev = useMemo(() => {
    if (!overviewKpisPrev) return null;
    const modeFactor = incidentCommandMode === "stabilize" ? 1 : incidentCommandMode === "mitigate" ? 0.65 : 0.35;
    const revenueFactor = incidentCommandMode === "stabilize" ? 1 : incidentCommandMode === "mitigate" ? 0.7 : 0.4;
    const impactedServices = Math.max(1, Math.round((overviewKpisPrev.affectedServices ?? 0) * modeFactor));
    const rootCauseConfidence = Math.max(35, Math.min(99, 62 + ((overviewKpisPrev.activeProblems ?? 0) > 0 ? 12 : 0)));
    const revenueAtRisk = (businessImpactPrev?.estimatedRevenueAtRisk ?? 0) * revenueFactor;
    return { impactedServices, rootCauseConfidence, revenueAtRisk };
  }, [overviewKpisPrev, incidentCommandMode, businessImpactPrev?.estimatedRevenueAtRisk]);

  const failurePatternsData = useMemo(() => {
    const patternMap = new Map<string, { pattern: string; count: number; confidence: number; playbook: string; drillLabel: string; drillUrl: string }>();
    const addPattern = (pattern: string, confidence: number, playbook: string, drillLabel: string, drillUrl: string) => {
      const prev = patternMap.get(pattern) ?? { pattern, count: 0, confidence, playbook, drillLabel, drillUrl };
      prev.count += 1;
      prev.confidence = Math.max(prev.confidence, confidence);
      patternMap.set(pattern, prev);
    };
    anomalyData.filter((a) => a.Anomaly === "YES").forEach((a: any) => {
      if ((a["Latency Change %"] ?? 0) > 50 && (a["Error Rate Change %"] ?? 0) > 100) {
        const url = `${envUrl}/ui/apps/dynatrace.distributedtracing/explorer?filter=span.status+%3D+Error&${tfParams(tfFrom, tfTo)}`;
        addPattern("Latency + Error Spike Cascade", 0.82, "Check downstream saturation, then apply load shedding.", "Open Distributed Traces (Gen3)", url);
      } else if ((a["Requests Δ %"] ?? 0) > 40 && (a["Error Rate Change %"] ?? 0) > 30) {
        const url = `${envUrl}/ui/apps/dynatrace.distributedtracing/explorer?${tfParams(tfFrom, tfTo)}`;
        addPattern("Traffic Surge Instability", 0.74, "Enable autoscale fast-path and verify rate limits.", "Open Distributed Traces (Gen3)", url);
      }
    });
    if (inferredDeployRegressionCount > 0) {
      const url = `${envUrl}/ui/apps/dynatrace.davis.problems/?${tfParams(tfFrom, tfTo)}`;
      addPattern("Post-Deployment Regression", 0.78, "Evaluate canary rollback and compare changed endpoints.", "Open Davis Problems (Gen3)", url);
    }
    if (problemsData.filter((p) => p.Status === "ACTIVE").length > 2) {
      const url = `${envUrl}/ui/apps/dynatrace.davis.problems/?${tfParams(tfFrom, tfTo)}`;
      addPattern("Multi-Service Incident Cluster", 0.7, "Run incident command flow and prioritize shared dependencies.", "Open Davis Problems (Gen3)", url);
    }
    return Array.from(patternMap.values()).sort((a, b) => b.count - a.count || b.confidence - a.confidence);
  }, [anomalyData, inferredDeployRegressionCount, problemsData, envUrl, tfFrom, tfTo]);

  const failurePatternsPrevSummary = useMemo(() => {
    if (!overviewKpisPrev) return null;
    let patternFamilies = 0;
    if ((overviewKpisPrev.avgP90 ?? 0) > 0 && (overviewKpisPrev.errorRate ?? 0) > 1.2) patternFamilies += 1;
    if ((overviewKpisPrev.totalRequests ?? 0) > 0 && (overviewKpisPrev.errorRate ?? 0) > 0.8) patternFamilies += 1;
    if (inferredDeployRegressionPrevCount > 0) patternFamilies += 1;
    if ((overviewKpisPrev.activeProblems ?? 0) > 2) patternFamilies += 1;
    const anomalousServices = svcDetailsPrevData.filter((s) => Number(s.FailureRate ?? 0) > 1.5 || Number(s.Latency_p90 ?? 0) > 500000).length;
    return {
      patternFamilies,
      activeProblems: overviewKpisPrev.activeProblems ?? 0,
      anomalousServices,
    };
  }, [overviewKpisPrev, inferredDeployRegressionPrevCount, svcDetailsPrevData]);

  const teamReliabilityData = useMemo(() => {
    const rows = new Map<string, { team: string; services: number; avgFailureRate: number; atRisk: number; deployRegressions: number; score: number }>();
    const regressionByService = inferredDeployRegressionsByService;
    svcDetailsData.forEach((s) => {
      const team = ownershipMap.get(s["dt.entity.service"]) || "Unassigned";
      const curr = rows.get(team) ?? { team, services: 0, avgFailureRate: 0, atRisk: 0, deployRegressions: 0, score: 100 };
      curr.services += 1;
      curr.avgFailureRate += Number(s.FailureRate ?? 0);
      if (Number(s.FailureRate ?? 0) >= 1 || Number(s.Latency_p90 ?? 0) / 1000 >= 500) curr.atRisk += 1;
      curr.deployRegressions += regressionByService.get(s.Service) ?? 0;
      rows.set(team, curr);
    });
    return Array.from(rows.values()).map((r) => {
      const avgFailureRate = r.services > 0 ? r.avgFailureRate / r.services : 0;
      const score = Math.max(0, Math.round(100 - avgFailureRate * 8 - r.atRisk * 4 - r.deployRegressions * 3));
      return { ...r, avgFailureRate, score };
    }).sort((a, b) => b.score - a.score);
  }, [svcDetailsData, inferredDeployRegressionsByService, ownershipMap]);

  // ─── Service Details: Last 5 deployments per service with metric delta ───
  const perServiceDeployments = useMemo(() => {
    const m = new Map<string, Array<{ time: string; event: string; latDelta: number | null; errDelta: number | null }>>();
    if (!deploymentsData.length || !changeImpactResult.data?.records) return m;
    // Build hourly metric data per service
    const metrics = changeImpactResult.data.records;
    const svcBuckets = new Map<string, { start: number; requests: number; failures: number; latency: number }[]>();
    metrics.forEach((r: any) => {
      const svcId = (r["dt.entity.service"] as string) ?? "";
      const tf2 = r["timeframe"] as any;
      const start = tf2?.start ? new Date(tf2.start).getTime() : 0;
      const reqArr = r["requests"] as number[] | null;
      const failArr = r["failures"] as number[] | null;
      const latArr = r["latency_p90"] as number[] | null;
      if (!reqArr || !start) return;
      reqArr.forEach((req, i) => {
        const bucketStart = start + i * 3600000;
        if (!svcBuckets.has(svcId)) svcBuckets.set(svcId, []);
        svcBuckets.get(svcId)!.push({ start: bucketStart, requests: req ?? 0, failures: failArr?.[i] ?? 0, latency: latArr?.[i] ?? 0 });
      });
    });
    // Group deployments by service, take last 5, compute delta
    const bySvc = new Map<string, typeof deploymentsData>();
    deploymentsData.forEach(d => {
      const list = bySvc.get(d["dt.entity.service"]) ?? [];
      list.push(d);
      bySvc.set(d["dt.entity.service"], list);
    });
    bySvc.forEach((deps, svcId) => {
      const sorted = [...deps].sort((a, b) => b.timestamp - a.timestamp).slice(0, 5);
      const buckets = svcBuckets.get(svcId) ?? [];
      const entries = sorted.map(d => {
        const ts = d.timestamp;
        const windowMs = 3 * 3600000;
        const before = buckets.filter(b => b.start >= ts - windowMs && b.start < ts);
        const after = buckets.filter(b => b.start >= ts && b.start < ts + windowMs);
        const avgBefore = before.length ? before.reduce((s, b) => s + b.latency, 0) / before.length : 0;
        const avgAfter = after.length ? after.reduce((s, b) => s + b.latency, 0) / after.length : 0;
        const reqBefore = before.reduce((s, b) => s + b.requests, 0);
        const reqAfter = after.reduce((s, b) => s + b.requests, 0);
        const failBefore = reqBefore > 0 ? (before.reduce((s, b) => s + b.failures, 0) / reqBefore) * 100 : 0;
        const failAfter = reqAfter > 0 ? (after.reduce((s, b) => s + b.failures, 0) / reqAfter) * 100 : 0;
        return {
          time: d.Time,
          event: d.Event,
          latDelta: avgBefore > 0 ? ((avgAfter - avgBefore) / avgBefore) * 100 : null,
          errDelta: before.length > 0 ? failAfter - failBefore : null,
        };
      });
      m.set(svcId, entries);
    });
    return m;
  }, [deploymentsData, changeImpactResult.data]);

  // ─── Change Impact Analysis ───
  const changeImpactData = useMemo(() => {
    if (!deploymentsResult.data?.records || !changeImpactResult.data?.records) return [];
    const deployments = deploymentsResult.data.records;
    const metrics = changeImpactResult.data.records;

    // Build per-service hourly buckets: { svcId -> [{ start, requests, failures, latency }] }
    const svcBuckets = new Map<string, { start: number; requests: number; failures: number; latency: number }[]>();
    metrics.forEach((r) => {
      const svcId = (r["dt.entity.service"] as string) ?? "";
      const tf = r["timeframe"] as any;
      const start = tf?.start ? new Date(tf.start).getTime() : 0;
      const reqArr = r["requests"] as number[] | null;
      const failArr = r["failures"] as number[] | null;
      const latArr = r["latency_p90"] as number[] | null;
      if (!reqArr || !start) return;
      // timeseries interval is a scalar Duration, not an array; compute bucket starts from timeframe.start
      const intervalMs = 3600000; // 1h matches the query interval
      reqArr.forEach((req, i) => {
        const bucketStart = start + i * intervalMs;
        if (!svcBuckets.has(svcId)) svcBuckets.set(svcId, []);
        svcBuckets.get(svcId)!.push({
          start: bucketStart,
          requests: req ?? 0,
          failures: failArr?.[i] ?? 0,
          latency: latArr?.[i] ?? 0,
        });
      });
    });

    // For each deployment, find 3h before and 3h after metrics
    const windowMs = 3 * 3600000;
    return deployments.map((d) => {
      const ts = d["timestamp"] ? new Date(d["timestamp"] as string).getTime() : 0;
      const svcId = (d["dt.entity.service"] as string) ?? "";
      const svcName = (d["serviceName"] as string) ?? "";
      const eventName = (d["event.name"] as string) ?? "";
      const buckets = svcBuckets.get(svcId) ?? [];

      const before = buckets.filter((b) => b.start >= ts - windowMs && b.start < ts);
      const after = buckets.filter((b) => b.start >= ts && b.start < ts + windowMs);

      const avg = (arr: number[]) => arr.length > 0 ? arr.reduce((a, b) => a + b, 0) / arr.length : 0;
      const sum = (arr: number[]) => arr.reduce((a, b) => a + b, 0);

      const beforeReq = sum(before.map((b) => b.requests));
      const afterReq = sum(after.map((b) => b.requests));
      const beforeLat = avg(before.map((b) => b.latency));
      const afterLat = avg(after.map((b) => b.latency));
      const beforeFail = beforeReq > 0 ? (sum(before.map((b) => b.failures)) / beforeReq) * 100 : 0;
      const afterFail = afterReq > 0 ? (sum(after.map((b) => b.failures)) / afterReq) * 100 : 0;

      const latDelta = beforeLat > 0 ? ((afterLat - beforeLat) / beforeLat) * 100 : 0;
      const reqDelta = beforeReq > 0 ? ((afterReq - beforeReq) / beforeReq) * 100 : 0;
      const failDelta = afterFail - beforeFail;

      let verdict = "✅ Healthy";
      if (latDelta > 50 || failDelta > 2) verdict = "🟥 Regression";
      else if (latDelta > 20 || failDelta > 0.5) verdict = "🟨 Warning";
      else if (latDelta < -10 && failDelta <= 0) verdict = "🟩 Improved";

      return {
        Time: ts ? new Date(ts).toLocaleString() : "",
        Deployment: eventName,
        Service: svcName,
        "dt.entity.service": svcId,
        "Requests (Before)": beforeReq,
        "Requests (After)": afterReq,
        "Requests Δ %": Math.round(reqDelta * 10) / 10,
        "Latency P90 (Before)": Math.round(beforeLat),
        "Latency P90 (After)": Math.round(afterLat),
        "Latency Δ %": Math.round(latDelta * 10) / 10,
        "Error Rate (Before)": Math.round(beforeFail * 1000) / 1000,
        "Error Rate (After)": Math.round(afterFail * 1000) / 1000,
        "Error Δ pp": Math.round(failDelta * 1000) / 1000,
        Verdict: verdict,
      };
    }).filter((d) => d.Service);
  }, [deploymentsResult.data, changeImpactResult.data]);

  // Sparkline: Change Impact regressions/warnings per time bucket
  const changeImpactSparklines = useMemo(() => {
    if (!changeImpactData.length || !deploymentsResult.data?.records?.length) return { regressions: [] as number[], warnings: [] as number[], rollbacks: [] as number[] };
    const start = timeframe.fromMs;
    const end = timeframe.toMs;
    const duration = end - start;
    if (duration <= 0) return { regressions: [], warnings: [], rollbacks: [] };
    const bucketCount = Math.min(48, Math.max(16, Math.round(duration / 1800000)));
    const bucketMs = duration / bucketCount;
    const regBuckets: number[] = new Array(bucketCount).fill(0);
    const warnBuckets: number[] = new Array(bucketCount).fill(0);
    const rollBuckets: number[] = new Array(bucketCount).fill(0);
    const deployRecords = deploymentsResult.data.records;
    deployRecords.forEach((d: any, idx: number) => {
      const ts = d["timestamp"] ? new Date(d["timestamp"] as string).getTime() : 0;
      if (ts >= start && ts < end && changeImpactData[idx]) {
        const b = Math.min(Math.floor((ts - start) / bucketMs), bucketCount - 1);
        const verdict = changeImpactData[idx]?.Verdict ?? "";
        if (verdict.includes("Regression")) regBuckets[b]++;
        if (verdict.includes("Warning")) warnBuckets[b]++;
      }
    });
    return { regressions: trimLastBucket(regBuckets), warnings: trimLastBucket(warnBuckets), rollbacks: trimLastBucket(rollBuckets) };
  }, [changeImpactData, deploymentsResult.data, timeframe.fromMs, timeframe.toMs]);

  // Prev-period change impact verdicts (for KPI comparison arrows)
  const changeImpactPrevVerdicts = useMemo(() => {
    if (!deploymentsPrevResult.data?.records || !changeImpactPrevResult.data?.records) return null;
    const deployments = deploymentsPrevResult.data.records;
    const metrics = changeImpactPrevResult.data.records;
    const svcBuckets = new Map<string, { start: number; requests: number; failures: number; latency: number }[]>();
    metrics.forEach((r) => {
      const svcId = (r["dt.entity.service"] as string) ?? "";
      const tf2 = r["timeframe"] as any;
      const start = tf2?.start ? new Date(tf2.start).getTime() : 0;
      const reqArr = r["requests"] as number[] | null;
      const failArr = r["failures"] as number[] | null;
      const latArr = r["latency_p90"] as number[] | null;
      if (!reqArr || !start) return;
      const intervalMs = 3600000;
      reqArr.forEach((req, i) => {
        const bucketStart = start + i * intervalMs;
        if (!svcBuckets.has(svcId)) svcBuckets.set(svcId, []);
        svcBuckets.get(svcId)!.push({ start: bucketStart, requests: req ?? 0, failures: failArr?.[i] ?? 0, latency: latArr?.[i] ?? 0 });
      });
    });
    const windowMs = 3 * 3600000;
    let regressions = 0, warnings = 0, rollbacks = 0;
    deployments.forEach((d) => {
      const ts = d["timestamp"] ? new Date(d["timestamp"] as string).getTime() : 0;
      const svcId = (d["dt.entity.service"] as string) ?? "";
      const buckets = svcBuckets.get(svcId) ?? [];
      const before = buckets.filter((b) => b.start >= ts - windowMs && b.start < ts);
      const after = buckets.filter((b) => b.start >= ts && b.start < ts + windowMs);
      const avg = (arr: number[]) => arr.length > 0 ? arr.reduce((a, b) => a + b, 0) / arr.length : 0;
      const sum = (arr: number[]) => arr.reduce((a, b) => a + b, 0);
      const beforeReq = sum(before.map((b) => b.requests));
      const afterReq = sum(after.map((b) => b.requests));
      const beforeLat = avg(before.map((b) => b.latency));
      const afterLat = avg(after.map((b) => b.latency));
      const beforeFail = beforeReq > 0 ? (sum(before.map((b) => b.failures)) / beforeReq) * 100 : 0;
      const afterFail = afterReq > 0 ? (sum(after.map((b) => b.failures)) / afterReq) * 100 : 0;
      const latDelta = beforeLat > 0 ? ((afterLat - beforeLat) / beforeLat) * 100 : 0;
      const failDelta2 = afterFail - beforeFail;
      if (latDelta > 50 || failDelta2 > 2) { regressions++; if (latDelta > 50 && failDelta2 > 2) rollbacks++; }
      else if (latDelta > 20 || failDelta2 > 0.5) warnings++;
    });
    return { regressions, warnings, rollbacks };
  }, [deploymentsPrevResult.data, changeImpactPrevResult.data]);

  // ─── Apdex / User Satisfaction ───
  const apdexData = useMemo(() => {
    if (!apdexResult.data?.records) return [];
    const svcMap = new Map<string, { satisfied: number; tolerating: number; frustrated: number; name: string; svcId: string }>();
    apdexResult.data.records.forEach((r) => {
      const svcId = (r["dt.entity.service"] as string) ?? "";
      const name = (r["Service"] as string) ?? svcId;
      const satisfaction = (r["satisfaction"] as string) ?? "";
      const cnt = Number(r["count"]) || 0;
      if (!svcMap.has(svcId)) svcMap.set(svcId, { satisfied: 0, tolerating: 0, frustrated: 0, name, svcId });
      const entry = svcMap.get(svcId)!;
      if (satisfaction === "satisfied") entry.satisfied += cnt;
      else if (satisfaction === "tolerating") entry.tolerating += cnt;
      else if (satisfaction === "frustrated") entry.frustrated += cnt;
    });
    return Array.from(svcMap.entries())
      .map(([_id, s]) => {
        const total = s.satisfied + s.tolerating + s.frustrated;
        const apdex = total > 0 ? (s.satisfied + s.tolerating / 2) / total : 1;
        const pctSatisfied = total > 0 ? (s.satisfied / total) * 100 : 100;
        const pctTolerating = total > 0 ? (s.tolerating / total) * 100 : 0;
        const pctFrustrated = total > 0 ? (s.frustrated / total) * 100 : 0;
        let rating = "Excellent";
        if (apdex < 0.5) rating = "Unacceptable";
        else if (apdex < 0.7) rating = "Poor";
        else if (apdex < 0.85) rating = "Fair";
        else if (apdex < 0.94) rating = "Good";
        return {
          Service: s.name,
          "dt.entity.service": s.svcId,
          Apdex: apdex.toFixed(2),
          ApdexNum: Math.round(apdex * 100) / 100,
          Rating: rating,
          Satisfied: s.satisfied,
          "Satisfied %": `${(Math.round(pctSatisfied * 10) / 10)}%`,
          Tolerating: s.tolerating,
          "Tolerating %": `${(Math.round(pctTolerating * 10) / 10)}%`,
          Frustrated: s.frustrated,
          "Frustrated %": `${(Math.round(pctFrustrated * 10) / 10)}%`,
          Total: total,
        };
      })
      .sort((a, b) => a.ApdexNum - b.ApdexNum); // worst first
  }, [apdexResult.data]);

  // ─── Apdex Previous Period (for compare) ───
  const apdexPrevMap = useMemo(() => {
    const map = new Map<string, number>();
    if (!apdexPrevResult.data?.records) return map;
    const svcMap = new Map<string, { satisfied: number; tolerating: number; frustrated: number }>();
    apdexPrevResult.data.records.forEach((r) => {
      const name = (r["Service"] as string) ?? "";
      const satisfaction = (r["satisfaction"] as string) ?? "";
      const cnt = Number(r["count"]) || 0;
      if (!svcMap.has(name)) svcMap.set(name, { satisfied: 0, tolerating: 0, frustrated: 0 });
      const entry = svcMap.get(name)!;
      if (satisfaction === "satisfied") entry.satisfied += cnt;
      else if (satisfaction === "tolerating") entry.tolerating += cnt;
      else if (satisfaction === "frustrated") entry.frustrated += cnt;
    });
    svcMap.forEach((s, name) => {
      const total = s.satisfied + s.tolerating + s.frustrated;
      map.set(name, total > 0 ? (s.satisfied + s.tolerating / 2) / total : 1);
    });
    return map;
  }, [apdexPrevResult.data]);

  const apdexCompareData = useMemo(() => {
    if (!apdexCompare) return [];
    const prevLoading = apdexPrevResult.isLoading;
    return apdexData.map((d) => {
      const prev = apdexPrevMap.get(d.Service);
      const prevApdex = prevLoading ? "Loading..." : prev !== undefined ? prev.toFixed(2) : "N/A";
      const delta = prevLoading ? "..." : prev !== undefined ? (d.ApdexNum - prev).toFixed(2) : "N/A";
      return { ...d, "Prev Apdex": prevApdex, "Δ Apdex": delta };
    });
  }, [apdexData, apdexPrevMap, apdexCompare, apdexPrevResult.isLoading]);

  // ─── Incident Timeline (combined) ───
  const timelineData = useMemo(() => {
    const events: { Time: string; Type: string; Description: string; Status: string; RootCause: string; eventId: string; ts: number }[] = [];
    // Add problems
    problemsData.forEach((p) => {
      const ts = p.StartTime ? new Date(p.StartTime).getTime() : 0;
      events.push({ Time: p.StartTime, Type: "Problem", Description: p.Description, Status: p.Status, RootCause: p.RootCause ?? "", eventId: p["event.id"] ?? "", ts });
    });
    // Add deployments
    deploymentsData.forEach((d) => {
      const ts = d.Time ? new Date(d.Time).getTime() : 0;
      events.push({ Time: d.Time, Type: "Deployment", Description: d.Event, Status: "—", RootCause: "", eventId: "", ts });
    });
    return events.sort((a, b) => b.ts - a.ts).map(({ ts, ...rest }) => rest);
  }, [problemsData, deploymentsData]);

  // ─── Incident Timeline — grouped by root cause ───
  const timelineGrouped = useMemo(() => {
    if (!timelineGroupByRoot) return null;
    const groups = new Map<string, typeof timelineData>();
    timelineData.forEach(e => {
      const key = e.RootCause || e.Description || "Ungrouped";
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key)!.push(e);
    });
    return Array.from(groups.entries())
      .map(([rootCause, events]) => ({ rootCause, events, count: events.length }))
      .sort((a, b) => b.count - a.count);
  }, [timelineData, timelineGroupByRoot]);

  // ─── Change Impact — detailed per-deploy cards with P50/P99/throughput ───
  const changeImpactCards = useMemo(() => {
    if (!deploymentsResult.data?.records || !changeImpactDetailedResult.data?.records) return [];
    const deployments = deploymentsResult.data.records;
    const metrics = changeImpactDetailedResult.data.records;
    const svcBuckets = new Map<string, { start: number; requests: number; failures: number; latP50: number; latP90: number; latP99: number }[]>();
    metrics.forEach((r: any) => {
      const svcId = (r["dt.entity.service"] as string) ?? "";
      const tf = r["timeframe"] as any;
      const start = tf?.start ? new Date(tf.start).getTime() : 0;
      const reqArr = r["requests"] as number[] | null;
      const failArr = r["failures"] as number[] | null;
      const latP50Arr = r["latency_p50"] as number[] | null;
      const latP90Arr = r["latency_p90"] as number[] | null;
      const latP99Arr = r["latency_p99"] as number[] | null;
      if (!reqArr || !start) return;
      const intervalMs = 3600000;
      reqArr.forEach((req, i) => {
        const bucketStart = start + i * intervalMs;
        if (!svcBuckets.has(svcId)) svcBuckets.set(svcId, []);
        svcBuckets.get(svcId)!.push({ start: bucketStart, requests: req ?? 0, failures: failArr?.[i] ?? 0, latP50: latP50Arr?.[i] ?? 0, latP90: latP90Arr?.[i] ?? 0, latP99: latP99Arr?.[i] ?? 0 });
      });
    });
    const windowMs = 3 * 3600000;
    return deployments.map((d: any) => {
      const ts = d["timestamp"] ? new Date(d["timestamp"] as string).getTime() : 0;
      const svcId = (d["dt.entity.service"] as string) ?? "";
      const svcName = (d["serviceName"] as string) ?? "";
      const eventName = (d["event.name"] as string) ?? "";
      const buckets = svcBuckets.get(svcId) ?? [];
      const before = buckets.filter(b => b.start >= ts - windowMs && b.start < ts);
      const after = buckets.filter(b => b.start >= ts && b.start < ts + windowMs);
      const avg = (arr: number[]) => arr.length > 0 ? arr.reduce((a, b) => a + b, 0) / arr.length : 0;
      const sum = (arr: number[]) => arr.reduce((a, b) => a + b, 0);
      const bP50 = avg(before.map(b => b.latP50));
      const aP50 = avg(after.map(b => b.latP50));
      const bP99 = avg(before.map(b => b.latP99));
      const aP99 = avg(after.map(b => b.latP99));
      const bP90 = avg(before.map(b => b.latP90));
      const aP90 = avg(after.map(b => b.latP90));
      const bReqs = sum(before.map(b => b.requests));
      const aReqs = sum(after.map(b => b.requests));
      const bErrRate = bReqs > 0 ? (sum(before.map(b => b.failures)) / bReqs) * 100 : 0;
      const aErrRate = aReqs > 0 ? (sum(after.map(b => b.failures)) / aReqs) * 100 : 0;
      const latDelta = bP90 > 0 ? ((aP90 - bP90) / bP90) * 100 : 0;
      const errDelta = aErrRate - bErrRate;
      const reqDelta = bReqs > 0 ? ((aReqs - bReqs) / bReqs) * 100 : 0;
      const rollback = latDelta > 20 && errDelta > 0.5 && reqDelta < -5;
      return { time: ts ? new Date(ts).toLocaleString() : "", deployment: eventName, service: svcName, svcId,
        before: { p50: Math.round(bP50), p90: Math.round(bP90), p99: Math.round(bP99), errorRate: Math.round(bErrRate * 1000) / 1000, throughput: bReqs },
        after: { p50: Math.round(aP50), p90: Math.round(aP90), p99: Math.round(aP99), errorRate: Math.round(aErrRate * 1000) / 1000, throughput: aReqs },
        delta: { latP90: Math.round(latDelta * 10) / 10, errRate: Math.round(errDelta * 1000) / 1000, throughput: Math.round(reqDelta * 10) / 10 },
        rollback,
      };
    }).filter((d: any) => d.service);
  }, [deploymentsResult.data, changeImpactDetailedResult.data]);

  // ─── Apdex — geographic segmentation ───
  const apdexGeoData = useMemo(() => {
    const records = apdexGeoResult.data?.records;
    if (!records?.length) return [];
    const regionMap = new Map<string, { satisfied: number; tolerating: number; frustrated: number }>();
    records.forEach((r: any) => {
      const region = (r["region"] as string) ?? "Unknown";
      const satisfaction = (r["satisfaction"] as string) ?? "";
      const cnt = Number(r["count"]) || 0;
      if (!regionMap.has(region)) regionMap.set(region, { satisfied: 0, tolerating: 0, frustrated: 0 });
      const entry = regionMap.get(region)!;
      if (satisfaction === "satisfied") entry.satisfied += cnt;
      else if (satisfaction === "tolerating") entry.tolerating += cnt;
      else entry.frustrated += cnt;
    });
    return Array.from(regionMap.entries()).map(([region, s]) => {
      const total = s.satisfied + s.tolerating + s.frustrated;
      const apdex = total > 0 ? (s.satisfied + s.tolerating / 2) / total : 1;
      return { Region: region, Apdex: Math.round(apdex * 100) / 100, Total: total, Satisfied: s.satisfied, Tolerating: s.tolerating, Frustrated: s.frustrated };
    }).sort((a, b) => a.Apdex - b.Apdex);
  }, [apdexGeoResult.data]);

  // ─── Apdex — cohort segmentation ───
  const apdexCohortData = useMemo(() => {
    const records = apdexCohortResult.data?.records;
    if (!records?.length) return [];
    const cohortMap = new Map<string, { satisfied: number; tolerating: number; frustrated: number }>();
    records.forEach((r: any) => {
      const cohort = (r["cohort"] as string) ?? "Unknown";
      const satisfaction = (r["satisfaction"] as string) ?? "";
      const cnt = Number(r["count"]) || 0;
      if (!cohortMap.has(cohort)) cohortMap.set(cohort, { satisfied: 0, tolerating: 0, frustrated: 0 });
      const entry = cohortMap.get(cohort)!;
      if (satisfaction === "satisfied") entry.satisfied += cnt;
      else if (satisfaction === "tolerating") entry.tolerating += cnt;
      else entry.frustrated += cnt;
    });
    return Array.from(cohortMap.entries()).map(([cohort, s]) => {
      const total = s.satisfied + s.tolerating + s.frustrated;
      const apdex = total > 0 ? (s.satisfied + s.tolerating / 2) / total : 1;
      return { Cohort: cohort, Apdex: Math.round(apdex * 100) / 100, Total: total, Satisfied: s.satisfied, Tolerating: s.tolerating, Frustrated: s.frustrated };
    }).sort((a, b) => a.Apdex - b.Apdex);
  }, [apdexCohortResult.data]);

  // ─── Apdex SLO integration ───
  const apdexSloStatus = useMemo(() => {
    if (!apdexData.length) return null;
    const target = sloTarget / 100; // e.g., 99.9 -> 0.999 → too strict. Use apdex target of 0.85
    const apdexTarget = 0.85;
    const avgApdex = apdexData.reduce((s, d) => s + d.ApdexNum, 0) / apdexData.length;
    const belowTarget = apdexData.filter(d => d.ApdexNum < apdexTarget);
    return { avgApdex: Math.round(avgApdex * 100) / 100, target: apdexTarget, met: avgApdex >= apdexTarget, belowCount: belowTarget.length, total: apdexData.length };
  }, [apdexData, sloTarget]);

  // ─── Alert Rule Evaluation ───
  const alertViolations = useMemo(() => {
    if (!alertRules.length || !svcDetailsData.length) return [];
    const violations: { Rule: string; Service: string; "dt.entity.service": string; Metric: string; Value: number; Threshold: number }[] = [];
    for (const rule of alertRules) {
      for (const svc of svcDetailsData) {
        if (rule.serviceName && svc.Service !== rule.serviceName) continue;
        const value = (svc as any)[rule.metric] as number ?? 0;
        const violated = rule.comparator === "gt" ? value > rule.threshold : value < rule.threshold;
        if (violated) {
          violations.push({
            Rule: `${rule.metric} ${rule.comparator === "gt" ? ">" : "<"} ${rule.threshold}`,
            Service: svc.Service as string,
            "dt.entity.service": svc["dt.entity.service"],
            Metric: rule.metric,
            Value: Math.round(value * 1000) / 1000,
            Threshold: rule.threshold,
          });
        }
      }
    }
    return violations;
  }, [alertRules, svcDetailsData]);

  // Batch 6: Alert noise ratio (must be after alertViolations)
  const alertNoiseRatioComputed = useMemo(() => {
    if (alertRules.length === 0) return [] as Array<{ ruleId: string; metric: string; fires: number; actionable: number; ratio: number }>;
    return alertRules.map(rule => {
      const fires = alertViolations.filter(v => v.Rule?.includes(rule.metric)).length;
      const distinctServices = new Set(alertViolations.filter(v => v.Rule?.includes(rule.metric)).map(v => v.Service)).size;
      return { ruleId: rule.id, metric: rule.metric, fires, actionable: distinctServices, ratio: fires > 0 ? distinctServices / fires : 1 };
    });
  }, [alertRules, alertViolations]);

  const addAlertRule = useCallback(() => {
    const rule: AlertRule = {
      id: Date.now().toString(),
      metric: newRuleMetric,
      comparator: newRuleComparator,
      threshold: newRuleThreshold,
      serviceName: newRuleService || undefined,
    };
    setAlertRules((prev) => [...prev, rule]);
  }, [newRuleMetric, newRuleComparator, newRuleThreshold, newRuleService]);

